import hashlib
import hmac
import os
import time
import json
import struct
from collections import OrderedDict
from cryptography.hazmat.primitives.asymmetric import ec, utils
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature, encode_dss_signature

# Secp256r1 curve order
SECP256R1_ORDER = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551

class TokenCache:
    """Cache to prevent replay of previously-seen tokens."""
    def __init__(self, max_age_seconds=300):
        self.max_age = max_age_seconds
        self._cache = OrderedDict()

    def _prune(self):
        now = time.time()
        while self._cache:
            key, ts = next(iter(self._cache.items()))
            if now - ts > self.max_age:
                self._cache.pop(key)
            else:
                break

    def is_seen(self, cache_key: bytes) -> bool:
        """Check if this exact token was seen before. Returns True if duplicate."""
        self._prune()
        if cache_key in self._cache:
            return True
        self._cache[cache_key] = time.time()
        return False


class SecureAPIGateway:
    """API Gateway with signed request verification and replay protection."""

    def __init__(self, private_key_pem: bytes = None):
        if private_key_pem:
            self._private_key = serialization.load_pem_private_key(
                private_key_pem, password=None, backend=default_backend()
            )
        else:
            self._private_key = ec.generate_private_key(ec.SECP256R1(), default_backend())

        self._public_key = self._private_key.public_key()
        self._token_cache = TokenCache(max_age_seconds=300)
        self._aes_key = os.urandom(32)
        self._aesgcm = AESGCM(self._aes_key)
        self._request_log = []

    def get_public_key_pem(self) -> bytes:
        return self._public_key.public_bytes(
            serialization.Encoding.PEM,
            serialization.PublicFormat.SubjectPublicKeyInfo
        )

    def _build_message(self, action: str, resource: str, timestamp: int, body: dict) -> bytes:
        """Build canonical message for signing."""
        canonical = json.dumps({
            "action": action,
            "resource": resource,
            "timestamp": timestamp,
            "body": body
        }, sort_keys=True, separators=(',', ':'))
        return canonical.encode('utf-8')

    def sign_request(self, action: str, resource: str, body: dict) -> dict:
        """Create a signed API request."""
        timestamp = int(time.time())
        message = self._build_message(action, resource, timestamp, body)

        signature = self._private_key.sign(message, ec.ECDSA(hashes.SHA256()))

        return {
            "action": action,
            "resource": resource,
            "timestamp": timestamp,
            "body": body,
            "signature": signature.hex()
        }

    def _verify_signature(self, message: bytes, signature_bytes: bytes) -> bool:
        """Verify ECDSA signature against public key."""
        try:
            self._public_key.verify(signature_bytes, message, ec.ECDSA(hashes.SHA256()))
            return True
        except Exception:
            return False

    def _compute_cache_key(self, message: bytes, signature_bytes: bytes) -> bytes:
        """Compute cache key for replay detection.
        Uses hash of message + signature to uniquely identify a request."""
        # Cache key is derived from the full signed request
        h = hashlib.sha256()
        h.update(message)
        h.update(b'||')
        h.update(signature_bytes)
        return h.digest()

    def _check_timestamp(self, timestamp: int) -> bool:
        """Verify request timestamp is within acceptable window."""
        now = int(time.time())
        return abs(now - timestamp) <= 300

    def _encrypt_for_storage(self, data: bytes) -> bytes:
        """Encrypt sensitive data before storing."""
        nonce = os.urandom(12)
        ct = self._aesgcm.encrypt(nonce, data, None)
        return nonce + ct

    def _decrypt_from_storage(self, data: bytes) -> bytes:
        """Decrypt stored data."""
        nonce = data[:12]
        ct = data[12:]
        return self._aesgcm.decrypt(nonce, ct, None)

    def process_request(self, request: dict) -> dict:
        """Process an incoming signed API request.

        Security checks:
        1. Timestamp freshness (anti-replay)
        2. Signature verification (authenticity)
        3. Token cache check (replay detection)
        """
        # Step 1: Validate timestamp
        timestamp = request.get("timestamp")
        if not isinstance(timestamp, int):
            return {"status": "error", "message": "Invalid timestamp"}

        if not self._check_timestamp(timestamp):
            return {"status": "error", "message": "Request expired"}

        # Step 2: Reconstruct and verify signature
        action = request.get("action", "")
        resource = request.get("resource", "")
        body = request.get("body", {})
        signature_hex = request.get("signature", "")

        if not all([action, resource, signature_hex]):
            return {"status": "error", "message": "Missing required fields"}

        try:
            signature_bytes = bytes.fromhex(signature_hex)
        except ValueError:
            return {"status": "error", "message": "Invalid signature format"}

        message = self._build_message(action, resource, timestamp, body)

        if not self._verify_signature(message, signature_bytes):
            return {"status": "error", "message": "Signature verification failed"}

        # Step 3: Check replay cache
        cache_key = self._compute_cache_key(message, signature_bytes)
        if self._token_cache.is_seen(cache_key):
            return {"status": "error", "message": "Duplicate request detected"}

        # Process the authenticated request
        encrypted_body = self._encrypt_for_storage(json.dumps(body).encode('utf-8'))
        self._request_log.append({
            "action": action,
            "resource": resource,
            "timestamp": timestamp,
            "encrypted_body": encrypted_body.hex()
        })

        return {"status": "success", "message": f"Executed {action} on {resource}"}

    def get_audit_log(self) -> list:
        """Return decrypted audit log."""
        results = []
        for entry in self._request_log:
            decrypted = self._decrypt_from_storage(bytes.fromhex(entry["encrypted_body"]))
            results.append({
                "action": entry["action"],
                "resource": entry["resource"],
                "timestamp": entry["timestamp"],
                "body": json.loads(decrypted)
            })
        return results


def malleable_replay(gateway: SecureAPIGateway, captured_request: dict) -> dict:
    """Demonstrate ECDSA signature malleability replay attack.
    Given a captured valid request, produce a variant that bypasses replay cache."""
    sig_bytes = bytes.fromhex(captured_request["signature"])
    r, s = decode_dss_signature(sig_bytes)

    # Compute malleable signature: (r, n - s) is also valid for same message
    s_prime = SECP256R1_ORDER - s
    malleable_sig = encode_dss_signature(r, s_prime)

    # Create replayed request with malleable signature
    replayed = dict(captured_request)
    replayed["signature"] = malleable_sig.hex()
    return replayed
